-- DEF-S3-076 / SRS_F003.R04, 5.2.4A: standard capability templates for the four simulated device types,
-- so a simulator can inherit the business capabilities of the type it simulates.
-- Parameter schemas come from the F2 demo fixtures. Idempotent.
INSERT INTO capability_template (device_type_code, template_code, template_name, capability_type, input_params, output_params, template_description)
VALUES ('BAGGAGE_SCANNER', 'CAP_BAGGAGE_MEASURE', '行李尺寸重量测量', 'CAP_BAGGAGE_MEASURE', $j$[{"name": "measureMode", "type": "String", "required": true, "defaultValue": "AUTO", "range": "AUTO/MANUAL"}, {"name": "timeout", "type": "Integer", "required": true, "defaultValue": "30", "range": "10~60"}]$j$::json, $j$[{"name": "length", "type": "Double", "required": true}, {"name": "width", "type": "Double", "required": true}, {"name": "height", "type": "Double", "required": true}, {"name": "weight", "type": "Double", "required": true}, {"name": "isOversize", "type": "Boolean", "required": true}, {"name": "measureStatus", "type": "String", "required": true}, {"name": "baggageInfo", "type": "String", "required": true}]$j$::json, '标准能力模板：行李尺寸重量测量')
ON CONFLICT (device_type_code, template_code) DO NOTHING;
