-- Back-fill existing simulators with the templates of their simulated type (UNTESTED, linked to the template).
INSERT INTO device_capabilities (device_id, template_id, capability_code, capability_name, capability_type,
                                 input_params, output_params, capability_status, capability_description)
SELECT d.id, t.id, t.template_code, t.template_name, t.capability_type,
       t.input_params, t.output_params, 'UNTESTED', t.template_description
FROM devices d
JOIN capability_template t ON t.device_type_code = d.simulated_device_type AND t.template_status = 'ACTIVE'
WHERE d.is_simulator = TRUE AND d.device_status <> 'DELETED'
  AND NOT EXISTS (SELECT 1 FROM device_capabilities c
                  WHERE c.device_id = d.id AND c.capability_code = t.template_code);

UPDATE capability_template t
SET usage_count = (SELECT COUNT(*) FROM device_capabilities c WHERE c.template_id = t.id);
